    quantity: float
    # `message` for SMS, WhatsApp and email, `minute` for calls.
    unit: Literal["message", "minute"]
    # The agent charged, on `usage`.
    agent: Union[str, None]
    # The conversation charged, on `usage`; `null` for a message sent with Create a message.
    conversation: Union[str, None]
    # The message or call charged, on `usage`.
    message: Union[str, None]
    # Id of the Stripe invoice, on `top_up` when Stripe issued one.
    invoice: str
    created: Required[str]


